#ifndef ZOVUTILS_TSORT_BACKEND_H
#define ZOVUTILS_TSORT_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
typedef struct {char*name;size_t indegree;size_t*to;size_t edges,cap;int emitted;} zov_tnode;
static inline char*zov_tsort_token(FILE*f){size_t n=0,cap=32;char*s=(char*)malloc(cap);if(!s)return NULL;int c;do{c=fgetc(f);}while(c!=EOF&&isspace((unsigned char)c));if(c==EOF){free(s);return NULL;}do{if(n+1>=cap){if(cap>SIZE_MAX/2){free(s);return NULL;}cap*=2;char*p=(char*)realloc(s,cap);if(!p){free(s);return NULL;}s=p;}s[n++]=(char)c;c=fgetc(f);}while(c!=EOF&&!isspace((unsigned char)c));s[n]=0;return s;}
static inline int zov_tsort_find(zov_tnode*n,size_t count,const char*s){for(size_t i=0;i<count;i++)if(!strcmp(n[i].name,s))return(int)i;return-1;}
static inline int zov_tsort_run(int argc,char**argv){const char*file=NULL;for(int i=0;i<argc;i++){if(!strcmp(argv[i],"--help")){puts("Usage: tsort [OPTION] [FILE]\nWrite totally ordered list consistent with the partial ordering in FILE.\nWith no FILE, or when FILE is -, read standard input.\n      --help     display this help and exit\n      --version  output version information and exit");return 0;}if(!strcmp(argv[i],"--version")){puts("tsort (zovutils) 0.10.12");return 0;}if(argv[i][0]=='-'&&strcmp(argv[i],"-")){fprintf(stderr,"tsort: unrecognized option '%s'\nTry 'tsort --help' for more information.\n",argv[i]);return 1;}if(file){fprintf(stderr,"tsort: extra operand '%s'\nTry 'tsort --help' for more information.\n",argv[i]);return 1;}file=argv[i];}FILE*f=stdin;if(file&&strcmp(file,"-")){f=fopen(file,"r");if(!f){fprintf(stderr,"tsort: %s: %s\n",file,strerror(errno));return 1;}}size_t cap=16,count=0;zov_tnode*nodes=(zov_tnode*)calloc(cap,sizeof(*nodes));if(!nodes){if(f!=stdin)fclose(f);return 1;}char*a=NULL,*b=NULL;int bad=0,odd=0;for(;;){a=zov_tsort_token(f);if(!a)break;b=zov_tsort_token(f);if(!b){free(a);odd=1;break;}char*pair[2]={a,b};int ids[2];for(int j=0;j<2;j++){ids[j]=zov_tsort_find(nodes,count,pair[j]);if(ids[j]<0){if(count==cap){size_t nc=cap*2;zov_tnode*p=(zov_tnode*)realloc(nodes,nc*sizeof(*nodes));if(!p){bad=1;break;}memset(p+cap,0,(nc-cap)*sizeof(*p));nodes=p;cap=nc;}ids[j]=(int)count;nodes[count++].name=pair[j];pair[j]=NULL;}}if(bad){free(pair[0]);free(pair[1]);break;}if(ids[0]!=ids[1]){zov_tnode*x=&nodes[ids[0]];int exists=0;for(size_t j=0;j<x->edges;j++)if(x->to[j]==(size_t)ids[1])exists=1;if(!exists){if(x->edges==x->cap){size_t nc=x->cap?x->cap*2:4;size_t*p=(size_t*)realloc(x->to,nc*sizeof(*p));if(!p){bad=1;free(pair[0]);free(pair[1]);break;}x->to=p;x->cap=nc;}x->to[x->edges++]=(size_t)ids[1];nodes[ids[1]].indegree++;}}free(pair[0]);free(pair[1]);}if(f!=stdin)fclose(f);if(bad){fprintf(stderr,"tsort: input contains an odd number of tokens\n");for(size_t i=0;i<count;i++){free(nodes[i].name);free(nodes[i].to);}free(nodes);return 1;}if(odd){fprintf(stderr,"tsort: %s: input contains an odd number of tokens\n",file?file:"-");for(size_t i=0;i<count;i++){free(nodes[i].name);free(nodes[i].to);}free(nodes);return 1;}size_t*queue=(size_t*)malloc((count?count:1)*sizeof(size_t));if(!queue){for(size_t i=0;i<count;i++){free(nodes[i].name);free(nodes[i].to);}free(nodes);return 1;}size_t qh=0,qt=0,done=0;for(size_t i=0;i<count;i++)if(!nodes[i].indegree)queue[qt++]=i;while(qh<qt){size_t x=queue[qh++];nodes[x].emitted=1;puts(nodes[x].name);done++;for(size_t j=0;j<nodes[x].edges;j++){size_t y=nodes[x].to[j];if(--nodes[y].indegree==0)queue[qt++]=y;}}int status=odd?1:0;if(odd)fprintf(stderr,"tsort: %s: input contains an odd number of tokens\n",file?file:"-");if(done<count){fprintf(stderr,"tsort: %s: input contains a loop:\n",file?file:"-");for(size_t i=0;i<count;i++)if(!nodes[i].emitted){fprintf(stderr,"tsort: %s\n",nodes[i].name);puts(nodes[i].name);}status=1;}free(queue);for(size_t i=0;i<count;i++){free(nodes[i].name);free(nodes[i].to);}free(nodes);return status;}
#endif
